import java.text.NumberFormat;
import java.time.*;
import java.time.format.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        var date = LocalDate.of(2026, 11, 20);
        System.out.println(date.format(DateTimeFormatter.ofLocalizedDate(FormatStyle.MEDIUM).withLocale(Locale.UK)));
        System.out.println(NumberFormat.getCurrencyInstance(Locale.UK).format(3.5));
    }
}
